CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','editor','admin')), preferences TEXT NOT NULL DEFAULT '{}', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS titles (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('movie','series','live')), year INTEGER, synopsis TEXT NOT NULL DEFAULT '', poster TEXT NOT NULL DEFAULT '', backdrop TEXT NOT NULL DEFAULT '', genres TEXT NOT NULL DEFAULT '[]', duration REAL, age_rating TEXT, cast_members TEXT NOT NULL DEFAULT '[]', director TEXT NOT NULL DEFAULT '', featured INTEGER NOT NULL DEFAULT 0, demo INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1, attribution TEXT NOT NULL DEFAULT '', trailer TEXT, intro_start REAL, intro_end REAL, recap_start REAL, recap_end REAL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS titles_identity ON titles(normalized,type,year);
CREATE INDEX IF NOT EXISTS titles_feed ON titles(published,type,created_at);
CREATE TABLE IF NOT EXISTS title_aliases (id TEXT PRIMARY KEY, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, name TEXT NOT NULL, normalized TEXT NOT NULL, UNIQUE(title_id,normalized));
CREATE INDEX IF NOT EXISTS title_alias_search ON title_aliases(normalized);
CREATE TABLE IF NOT EXISTS title_metadata_locks (title_id TEXT PRIMARY KEY REFERENCES titles(id) ON DELETE CASCADE, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS metadata_identifiers (id TEXT PRIMARY KEY, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, provider TEXT NOT NULL, external_id TEXT NOT NULL, UNIQUE(provider,external_id));
CREATE TABLE IF NOT EXISTS seasons (id TEXT PRIMARY KEY, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, number INTEGER NOT NULL, UNIQUE(title_id,number));
CREATE TABLE IF NOT EXISTS episodes (id TEXT PRIMARY KEY, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, season_id TEXT NOT NULL REFERENCES seasons(id) ON DELETE CASCADE, season INTEGER NOT NULL, number INTEGER NOT NULL, name TEXT NOT NULL, duration REAL, intro_start REAL, intro_end REAL, recap_start REAL, recap_end REAL, UNIQUE(title_id,season,number));
CREATE TABLE IF NOT EXISTS playlists (id TEXT PRIMARY KEY, name TEXT NOT NULL, url_encrypted TEXT, content_encrypted TEXT, enabled INTEGER NOT NULL DEFAULT 1, interval_hours REAL NOT NULL DEFAULT 24, last_sync BIGINT, next_sync BIGINT, health TEXT NOT NULL DEFAULT 'unknown', error TEXT, entry_count INTEGER NOT NULL DEFAULT 0, authorized INTEGER NOT NULL DEFAULT 1, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS playlists_due ON playlists(enabled,next_sync);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, playlist_id TEXT REFERENCES playlists(id) ON DELETE CASCADE, entry_key TEXT NOT NULL, name TEXT NOT NULL, url_encrypted TEXT NOT NULL, url_hash TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'unknown', health TEXT NOT NULL DEFAULT 'unknown', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 0, quality TEXT, last_checked BIGINT, last_success BIGINT, last_failure BIGINT, error TEXT, failures INTEGER NOT NULL DEFAULT 0, successes INTEGER NOT NULL DEFAULT 0, removed INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, UNIQUE(playlist_id,entry_key));
CREATE INDEX IF NOT EXISTS sources_availability ON sources(title_id,episode_id,health,enabled,removed);
CREATE INDEX IF NOT EXISTS sources_health_due ON sources(enabled,removed,last_checked);
CREATE TABLE IF NOT EXISTS source_health_history (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE, health TEXT NOT NULL, error TEXT, latency_ms INTEGER, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS health_history_source ON source_health_history(source_id,created_at);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 4, run_after BIGINT NOT NULL, lease_until BIGINT, lease_owner TEXT, created_at BIGINT NOT NULL, completed_at BIGINT, error TEXT, report TEXT, dedupe_key TEXT);
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs(status,run_after,lease_until);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_active_dedupe ON jobs(dedupe_key) WHERE status IN ('queued','running') AND dedupe_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS playlist_versions (id TEXT PRIMARY KEY, playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE, content_encrypted TEXT NOT NULL, content_hash TEXT NOT NULL, report TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS playlist_versions_history ON playlist_versions(playlist_id,created_at);
CREATE TABLE IF NOT EXISTS review_queue (id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id) ON DELETE CASCADE, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, candidate_id TEXT REFERENCES titles(id) ON DELETE SET NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS playback_progress (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, item_key TEXT NOT NULL, position REAL NOT NULL, duration REAL NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,item_key));
CREATE TABLE IF NOT EXISTS watch_history (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, position REAL NOT NULL, duration REAL NOT NULL, updated_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS history_user ON watch_history(user_id,updated_at);
CREATE INDEX IF NOT EXISTS history_trending ON watch_history(updated_at,title_id,user_id);
CREATE INDEX IF NOT EXISTS history_popularity ON watch_history(title_id,user_id);
CREATE TABLE IF NOT EXISTS watchlist (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,title_id));
CREATE TABLE IF NOT EXISTS favorites (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,title_id));
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_recent ON audit_log(created_at);
CREATE TABLE IF NOT EXISTS rate_limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at BIGINT NOT NULL);
